/**
 * This function is an experiment to theme the UI based around the currently
 * playing album artwork. Most of the code in this file is AI generated by
 * Claude Opus, and inspired by similar code in the iOS app for MusicBox.
 **/

import { formatCss, formatRgb, hsv, oklch } from "culori";

interface Oklch {
  l: number;
  c: number;
  h: number;
}

interface ExtractColorOptions {
  maxBrightness?: number; // 0–1, default 0.7
  sampleSize?: number; // default 16
}

const DEFAULT_RESET_COLOR =
  document.querySelector<HTMLMetaElement>("meta[name=theme-color]")?.content ||
  "transparent";

// Spring constants — tune to taste.
// Higher stiffness = snappier, higher damping = less bounce.
const STIFFNESS = 120;
const DAMPING = 20;
const MASS = 1;

// Current spring position and velocity in OKLCh space.
let pos: Oklch = { l: 0, c: 0, h: 0 };
let vel: Oklch = { l: 0, c: 0, h: 0 };
let target: Oklch = { l: 0, c: 0, h: 0 };
let lastTime: number | null = null;
let animationFrame: number | null = null;

export function updateAccentColor(
  img: HTMLImageElement,
  options: ExtractColorOptions = {},
): string | null {
  const { maxBrightness = 0.7, sampleSize = 16 } = options;
  const data = drawAndSample(img, sampleSize);
  if (!data) return null;

  const newColor = dominantColor(data, sampleSize, maxBrightness);
  setBackgroundColor(newColor);
  setThemeColorMeta(newColor);
  return newColor;
}

export function resetAccentColor(): string {
  document.body.style.setProperty("--gradient-tint", "var(--color-mist-600)");
  setThemeColorMeta(DEFAULT_RESET_COLOR);
  return DEFAULT_RESET_COLOR;
}

// --- Spring-animated background tint ----------------------------------------

function setBackgroundColor(rgbStr: string): void {
  const next = toOklch(rgbStr);
  // Reframe target hue so we always travel the short arc from current position.
  next.h = pos.h + shortHueDelta(pos.h, next.h);
  target = next;

  if (animationFrame !== null) return; // already running, just update target
  lastTime = null;
  animationFrame = requestAnimationFrame(tick);
}

function tick(now: number): void {
  if (lastTime === null) lastTime = now;
  // Clamp dt so a tab-switch doesn't cause a huge jump.
  const dt = Math.min((now - lastTime) / 600, 1 / 30);
  lastTime = now;

  let settled = true;

  for (const k of ["l", "c", "h"] as const) {
    const displacement = pos[k] - target[k];
    const springForce = -STIFFNESS * displacement;
    const dampingForce = -DAMPING * vel[k];
    const accel = (springForce + dampingForce) / MASS;

    vel[k] += accel * dt;
    pos[k] += vel[k] * dt;

    if (Math.abs(displacement) > 0.0001 || Math.abs(vel[k]) > 0.0001) {
      settled = false;
    }
  }

  document.body.style.setProperty(
    "--gradient-tint",
    formatCss({ mode: "oklch", l: pos.l, c: pos.c, h: pos.h }),
  );

  if (settled) {
    pos = { ...target };
    vel = { l: 0, c: 0, h: 0 };
    animationFrame = null;
  } else {
    animationFrame = requestAnimationFrame(tick);
  }
}

function toOklch(rgbStr: string): Oklch {
  const c = oklch(rgbStr);
  if (!c) return { l: 0, c: 0, h: 0 };
  return { l: c.l, c: c.c, h: c.h ?? 0 };
}

function shortHueDelta(from: number, to: number): number {
  let d = to - from;
  if (d > 180) d -= 360;
  else if (d < -180) d += 360;
  return d;
}

function setThemeColorMeta(color: string): void {
  const tags = document.documentElement.querySelectorAll(
    "meta[name=theme-color]",
  );
  for (const tag of tags) {
    tag.setAttribute("content", color);
  }
}

// --- Dominant color extraction ----------------------------------------------

function drawAndSample(
  img: HTMLImageElement,
  size: number,
): Uint8ClampedArray | null {
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  if (!ctx) return null;
  ctx.drawImage(img, 0, 0, size, size);
  return ctx.getImageData(0, 0, size, size).data;
}

function dominantColor(
  data: Uint8ClampedArray,
  size: number,
  maxBrightness: number,
): string {
  let sinSum = 0;
  let cosSum = 0;
  let weightedS = 0;
  let weightedV = 0;
  let totalWeight = 0;

  const count = size * size;

  for (let i = 0; i < count; i++) {
    const offset = i * 4;
    const pixel = hsv({
      mode: "rgb",
      r: data[offset] / 255,
      g: data[offset + 1] / 255,
      b: data[offset + 2] / 255,
    });
    if (!pixel) continue;
    // Hue is undefined for grays; default to 0 (it'll get zero weight anyway).
    const h = pixel.h ?? 0;
    const s = pixel.s;
    const v = pixel.v;

    // Skip very dark or near-white pixels.
    if (v <= 0.15 || v >= 0.95) continue;

    // Weight colorful pixels more heavily.
    const weight = s * s + 0.05;
    const angle = (h * Math.PI) / 180;
    sinSum += Math.sin(angle) * weight;
    cosSum += Math.cos(angle) * weight;
    weightedS += s * weight;
    weightedV += v * weight;
    totalWeight += weight;
  }

  if (totalWeight === 0) {
    return fallbackAverageColor(data, count, maxBrightness);
  }

  let avgH = (Math.atan2(sinSum, cosSum) * 180) / Math.PI;
  if (avgH < 0) avgH += 360;

  const avgS = weightedS / totalWeight;
  const avgV = weightedV / totalWeight;

  return (
    formatRgb({
      mode: "hsv",
      h: avgH,
      s: Math.min(avgS * 1.5, 1),
      v: Math.min(Math.max(avgV, 0.3), maxBrightness),
    }) ?? DEFAULT_RESET_COLOR
  );
}

function fallbackAverageColor(
  data: Uint8ClampedArray,
  count: number,
  maxBrightness: number,
): string {
  let totalR = 0;
  let totalG = 0;
  let totalB = 0;
  for (let i = 0; i < count; i++) {
    const offset = i * 4;
    totalR += data[offset];
    totalG += data[offset + 1];
    totalB += data[offset + 2];
  }
  const avg = hsv({
    mode: "rgb",
    r: totalR / count / 255,
    g: totalG / count / 255,
    b: totalB / count / 255,
  });
  if (!avg) return DEFAULT_RESET_COLOR;
  return (
    formatRgb({
      mode: "hsv",
      h: avg.h ?? 0,
      s: Math.min(avg.s * 1.5, 1),
      v: Math.min(Math.max(avg.v, 0.3), maxBrightness),
    }) ?? DEFAULT_RESET_COLOR
  );
}
